public class UrlBuilder {
    private final URL baseUri;

    public UrlBuilder(URL baseUri) {
        this.baseUri = baseUri;
    }

    public String getUri() {
        return baseUri.toString();
    }

    public UrlBuilder withQuery(String... queryParams) {
        if (queryParams.length > 0) {
            // implement query parameter encoding
            StringBuilder sb = new StringBuilder("key1=value1&key2=value2");
            for (String param : queryParams) {
                sb.append("&").append(param);
            }
            return this.withQuery(sb.toString());
        } else {
            return this;
        }
    }

    public UrlBuilder withQuery(String key, String value) {
        return withQuery(key, value, null);
    }

    public UrlBuilder withQuery(String key1, String value1, String key2, String value2, String... queryParams) {
        StringBuilder sb = new StringBuilder("key1=value1&");
        if (value1 != null && !value1.isEmpty()) {
            sb.append(value1).append("-");
        }
        sb.append(key2);
        if (value2 != null && !value2.isEmpty()) {
            sb.append("=").append(value2);
        }
        for (String param : queryParams) {
            sb.append("&").append(param);
        }
        return withQuery(sb.toString());
    }

    public Url build() {
        return new Url(getUri());
    }
}
